use serde_json::{json,Value};
use ubu_core::{AdvisoryCandidate,AuthoritySource,ObjectType,UbuId,UbuTimestamp,VersionRef,worker::LocalAdvisoryResultStatus};
use ubu_orchestrator::{config::ServerConfig,state::AppState,planning_time::FixedClock,services::{precondition_review as review,advisory_wire}};
use ubu_store::{UbuStore,models::object_record::NewObjectRecord,api::{admission::store_advisory_candidate,review::get_advisory_candidate}};
use std::path::Path;

fn load(root:&Path,name:&str)->Value {serde_json::from_str(&std::fs::read_to_string(root.join(format"'!("{name}.json"))).unwrap()).unwrap()}
fn save(root:&Path,name:&str,value:&Value) {std::fs::write(root.join(format!("{name}.json")),serde_json::to_string_pretty(value).unwrap()).unwrap()}
async fn count(pool:&sqlx::SqlitePool,table:&str)->i64 {sqlx::query_scalar(&format!("SELECT COUNT(*) FROM {table}")).fetch_one(pool).await.unwrap()}
async fn snapshot(pool:&sqlx::SqlitePool)->Vec<(String,Vec<String>)> {
 use sqlx::Row;
 let names:Vec<String>=sqlx::query_scalar("SELECT name FROM sqlite_master WHERE type='"'table' AND name NOT IN ('advisory_candidates','mutation_envelopes','sqlite_sequence') ORDER BY name\").fetch_all(pool).await.unwrap();
 let mut output=vec"'![];
 for name in names {
  let columns=sqlx::query(&format!("PRAGMA table_info('"\\\"{name}\\\")\")).fetch_all(pool).await.unwrap();
  let expr=columns.iter().map(|row|format"'!("quote('"\\\"{}\\\")\",row.get::<String,_>(\"name\"))).collect::<Vec<_>>().join(\" || '|' || \");
  let mut rows:Vec<String>=sqlx::query_scalar(&format"'!("SELECT {expr} FROM '"\\\"{name}\\\"\")).fetch_all(pool).await.unwrap();rows.sort();output.push((name,rows));
 } output
}
async fn run(root:&Path) {
 let now=UbuTimestamp::parse(\"2026-09-19T09:00:00Z\").unwrap();
 let state=AppState::in_memory(ServerConfig::from_env()).await.unwrap().with_clock(FixedClock(now));
 let baseline=load(root,\"baseline\");
 let task_id=baseline[\"target_refs\"][0][\"id\"].as_str().unwrap();
 let existing=baseline[\"normalized_proposal\"][\"existing_precondition\"].clone();
 let task=json"'!({"id":task_id,"title":"Synthetic carrier probe","description":"Synthetic carrier probe.","status":"active","preconditions":existing,"provenance":{"created_at":now,"authority_source":"user"}});
 let env=state.envelope_for([(UbuId::parse(task_id).unwrap(),VersionRef::Absent)].into_iter().collect(),AuthoritySource::User,now).unwrap();
 ubu_store::queries::admit_object(state.inner().store.pool(),&env,NewObjectRecord{id:task_id.into(),object_type:ObjectType::Task.as_str().into(),version:1,status:"active".into(),compartment_label:"default".into(),payload:task,created_at:now.to_string(),updated_at:now.to_string()}).await.unwrap();
 let context=review::Context{force:false,tasks:vec![review::ReviewTask{id:task_id.into(),description:"Synthetic carrier probe.".into(),existing_precondition:existing.clone(),existing_words:review::words(&existing),prior_rejection_reason:None}],targets:vec![]};
 let sub=review::submission(&state,&context,"synthetic-carrier-probe").await.unwrap();
 let canonical=snapshot(state.inner().store.pool()).await;
 let ledger=count(state.inner().store.pool(),"mutation_envelopes").await;
 let mut results=serde_json::Map::new();
 for name in ["baseline","inline","unknown","normalized-extra"] {
  let raw=load(root,name);
  let c:AdvisoryCandidate=serde_json::from_value(raw.clone()).unwrap();c.validate().unwrap();
  let serialized=serde_json::to_value(&c).unwrap();assert_eq!(serialized,raw);
  let c:AdvisoryCandidate=serde_json::from_str(&serde_json::to_string(&c).unwrap()).unwrap();assert_eq!(serde_json::to_value(&c).unwrap(),raw);
  let mut result=advisory_wire::empty_result(&sub);result.proposed_candidates.push(c);
  review::vet_result(&state,&sub,&mut result).await.unwrap();
  let malformed=result.status==LocalAdvisoryResultStatus::MalformedResult;
  if name=="normalized-extra" {assert!(malformed);assert_eq!(result.proposed_candidates.len(),0);}
  else {
   assert!(!malformed);assert_eq!(result.proposed_candidates.len(),1);
   let out=serde_json::to_value(&result.proposed_candidates[0]).unwrap();
   assert_eq!(out["payload"]["value"],baseline["normalized_proposal"]);
   assert!(out["payload"]["value"].get("perceptual_qualifiers").is_none());
   save(root,&format!("normalized-{name}"),&out);
  }
  results.insert(name.into(),json!({"core_roundtrip_equal":true,"normalization_status":result.status,"surviving_candidates":result.proposed_candidates.len(),"qualifiers_after":result.proposed_candidates.first().map(|c|serde_json::to_value(c).unwrap()["payload"]["value"]["perceptual_qualifiers"].clone()),"diagnostics":result.diagnostics}));
 }
 assert_eq!(snapshot(state.inner().store.pool()).await,canonical);
 assert_eq!(count(state.inner().store.pool(),"mutation_envelopes").await,ledger);
 let raw=load(root,"inline");let c:AdvisoryCandidate=serde_json::from_value(raw.clone()).unwrap();
 let env=state.envelope_for(Default::default(),AuthoritySource::User,now).unwrap();
 let url=format!("sqlite://{}",root.join("candidate.sqlite").display());
 let store=UbuStore::connect(&url).await.unwrap();
 let rec=store_advisory_candidate(store.pool(),&env,c.clone()).await.unwrap();assert_eq!(serde_json::to_value(rec.candidate().unwrap()).unwrap(),raw);
 store.pool().close().await;drop(store);
 let store=UbuStore::connect(&url).await.unwrap();
 let rec=get_advisory_candidate(store.pool(),&c.advisory_candidate_id).await.unwrap().unwrap();let retrieved=serde_json::to_value(rec.candidate().unwrap()).unwrap();assert_eq!(retrieved,raw);save(root,"store-reloaded",&retrieved);
 let replay=store_advisory_candidate(store.pool(),&env,c.clone()).await.unwrap();assert_eq!(serde_json::to_value(replay.candidate().unwrap()).unwrap(),raw);
 assert_eq!(count(store.pool(),"advisory_candidates").await,1);assert_eq!(count(store.pool(),"mutation_envelopes").await,1);
 assert_eq!(count(store.pool(),"objects").await,0);assert_eq!(count(store.pool(),"logs").await,0);
 let mut changed=c.clone();changed.payload=ubu_core::CandidatePayload::Inline(json!({"changed":true}));
 let collision=store_advisory_candidate(store.pool(),&env,changed).await;assert!(collision.is_err());
 results.insert("store".into(),json!({"restart_retrieval_equal":true,"exact_replay_equal":true,"candidate_count":1,"ledger_count":1,"object_count":0,"log_count":0,"changed_content_key_reuse_error":collision.err().unwrap().to_string()}));
 store.pool().close().await;
 // Separate direct store/API control; this deliberately bypasses normalization.
 store_advisory_candidate(state.inner().store.pool(),&env,c.clone()).await.unwrap();
 let response=ubu_orchestrator::api::advisory::candidate(axum::extract::State(state.clone()),axum::extract::Path(c.advisory_candidate_id.as_str().into())).await.unwrap();
 assert_eq!(response.0.candidate,raw);save(root,"api-candidate",&serde_json::to_value(&response.0).unwrap());
 let queue=ubu_orchestrator::api::advisory::queue(axum::extract::State(state.clone())).await.unwrap();assert_eq!(queue.0.candidates.len(),1);assert_eq!(queue.0.candidates[0].candidate,raw);
 save(root,"api-queue",&serde_json::to_value(&queue.0).unwrap());
 results.insert("api".into(),json!({"candidate_equal":true,"queue_candidate_equal":true,"state_category":response.0.state_category,"normalization_bypassed":true}));
 assert_eq!(snapshot(state.inner().store.pool()).await,canonical);
 let summary=Value::Object(results);save(root,"results",&summary);println!("{}",serde_json::to_string_pretty(&summary).unwrap());
}
fn main(){let arg=std::env::args().nth(1).unwrap();let root=Path::new(&arg);tokio::runtime::Runtime::new().unwrap().block_on(run(root));}
