 let rec=get_advisory_candidate(store.pool(),&c.advisory_candidate_id).await.unwrap().unwrap();let retrieved=serde_json::to_value(rec.candidate().unwrap()).unwrap();assert_eq!(retrieved,raw);save(root,"store-reloaded",&retrieved);
